'use strict';
let strategyCountry='MEX',strategyChild='mat',strategyHorizon='now',strategyScenario='fast';
function renderFamilyStrategy(){
 const f=DATA.family_strategy,root=document.querySelector('#strategy-content');if(!f||!root)return;
 const child=f.children[strategyChild],base=f.bases.find(b=>b.iso===strategyCountry),h=f.horizons.find(x=>x.id===strategyHorizon),scenario=(f.scenarios||[]).find(x=>x.id===strategyScenario);
 const links=xs=>xs.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('');
 root.innerHTML=`<div class="strategy-intro"><div><p class="section-kicker">DECISIÓN FAMILIAR · ${esc(f.checked)}</p><h3>Es una base.<br>dos de su propio <em>itinerario.</em></h3><p>${esc(f.conclusion)}</p><span class="strategy-editorial">Recomendación por el archivo encontrado · lugares aún no confirmados</span></div><div class="strategy-blueprint" aria-label="desarrollo a través de la práctica, el equipo y el propio producto"><div class="strategy-orbit"></div><div class="strategy-node sn-one"><span>01</span><b>estudiar</b><small>matemáticas · código</small></div><div class="strategy-node sn-two"><span>02</span><b>Crear</b><small>robot · prototipo</small></div><div class="strategy-node sn-three"><span>03</span><b>comprobar</b><small>Comando · usuario</small></div><div class="strategy-core" aria-hidden="true">✦</div></div></div>
 <div class="strategy-thesis"><b>mi criterio de traslado</b><p>${esc(f.decision)}</p><p>${esc(f.rationale)}</p></div>
 ${scenario?`<div class="strategy-heading"><h3>tres escenarios para la comparación</h3><p>${esc(f.confidence)}</p></div><div class="strategy-scenario-tabs" role="group" aria-label="escenario de la base permanente">${f.scenarios.map(x=>`<button data-strategy-scenario="${esc(x.id)}" aria-pressed="${x.id===strategyScenario}" class="${x.id===strategyScenario?'active':''}">${esc(x.name)}</button>`).join('')}</div><article class="strategy-scenario" data-selected-scenario="${esc(scenario.id)}"><div><p class="section-kicker">ESCENARIO · ${esc(scenario.iso)}</p><h4>${esc(scenario.title)}</h4><p>${esc(scenario.detail)}</p><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(scenario[strategyChild])}</p></div><ol>${scenario.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article>`:''}
 <div class="strategy-child-switch" role="group" aria-label="el recorrido del niño">${Object.entries(f.children).map(([id,c])=>`<button data-strategy-child="${id}" aria-pressed="${id===strategyChild}" class="${id===strategyChild?'active':''}">${esc(c.name)} <small>${esc(c.birth_year)}</small></button>`).join('')}<span>Una base familiar, un papel para todos.</span></div>
 <section class="strategy-child-route" aria-label="recomendación al niño"><p class="section-kicker">${esc(child.name.toUpperCase())} · AHORA</p><h4>${esc(child.default)}</h4><p>${esc(child.detail)}</p><ul>${child.current.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="strategy-proof"><b>La próxima temporada:</b> ${esc(child.proof)}</p><div class="strategy-sources">${links(child.sources)}</div></section>
 <div class="strategy-heading"><h3>donde construir un entorno permanente</h3><p>La evaluación de los datos de la escuela y las condiciones de entrada se muestran por separado.</p></div>
 <div class="strategy-base-grid" role="group" aria-label="la elección de la base familiar">${f.bases.map((b,i)=>`<button data-strategy-country="${esc(b.iso)}" aria-pressed="${b.iso===strategyCountry}" class="strategy-base ${b.iso===strategyCountry?'active':''}"><span class="strategy-base-code">${esc(b.iso)}</span><b>${esc(b.name.split(' · ')[0])}</b><small>${esc(b.verdict)}</small></button>`).join('')}</div>
 <article class="strategy-country-detail" data-selected-base="${esc(base.iso)}"><div><p class="section-kicker">${esc(base.role.toUpperCase())}</p><h3>${esc(base.name)}</h3><p class="strategy-opinion">${esc(base.recommendation)}</p><div class="strategy-verified"><b>que se describe oficialmente</b><p>${esc(base.verified)}</p></div><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(base.child_notes[strategyChild])}</p></div><div class="strategy-gates"><h4>¿Qué es lo que deciden las opciones?</h4><ul>${base.gates.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><b>el siguiente paso:</b> ${esc(base.next)}</p><div class="strategy-school-links">${base.school_ids.map(id=>`<button class="button secondary" data-school-open="${id}">${esc(DATA.schools.find(x=>x.id===id).name)} · dossier ↗</button>`).join('')}</div></div><div class="strategy-sources">${links(base.sources)}</div></article>
 ${f.cost_comparison?`<div class="strategy-heading"><h3>la enseñanza de ambos ${esc(f.cost_comparison.school_year)}</h3><p>${esc(f.cost_comparison.note)}</p></div><div class="strategy-cost-grid">${f.cost_comparison.schools.map(x=>`<article class="strategy-cost" data-cost-school="${esc(x.school_id)}"><p class="section-kicker">${esc(x.iso)} · DOS NIÑOS</p><h4>${esc(x.name)}</h4><dl><dt>formación anual / cobros anuales indicados</dt><dd>${esc(x.annual)}</dd><dt>las contribuciones únicas / solicitudes</dt><dd>${esc(x.entry)}</dd><dt>el primer año / la obligación total</dt><dd class="strategy-cost-total">${esc(x.first)}</dd></dl><details><summary>¿Cómo se calcula y qué no se incluye?</summary><p>${esc(x.formula)}</p></details><div class="strategy-sources"><a href="${esc(x.url)}" target="_blank" rel="noopener">el precio de la escuela · 2026–27 ↗</a><button class="button secondary" data-school-open="${esc(x.school_id)}">archivo de la escuela</button></div></article>`).join('')}</div>`:''}
 <div class="strategy-heading"><h3>Ingeniero, desarrollador, creador de productos.</h3><p>En la edad temprana, se puede combinar estas áreas.</p></div>
 <div class="strategy-track-grid">${f.tracks.map((t,i)=>`<article class="strategy-track"><span>0${i+1}</span><h4>${esc(t.name)}</h4><p>${esc(t.detail)}</p><p class="strategy-child-note">${esc(t[strategyChild])}</p><p><b>signo del resultado:</b> ${esc(t.proof)}</p></article>`).join('')}</div>
 <div class="strategy-heading"><h3>cómo el camino cambia con el tiempo</h3><p>Los próximos años  el plan de desarrollo. La admisión se revisa según las reglas de cada temporada.</p></div>
 <div class="strategy-horizon-tabs" role="group" aria-label="el horizonte de desarrollo">${f.horizons.map(x=>`<button data-strategy-horizon="${esc(x.id)}" aria-pressed="${x.id===strategyHorizon}" class="${x.id===strategyHorizon?'active':''}">${esc(x.name)}</button>`).join('')}</div>
 <article class="strategy-horizon" data-selected-horizon="${esc(h.id)}"><h4>${esc(h.name)}</h4><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(h[strategyChild])}</p><p>${esc(h.base)}</p><p class="strategy-proof">${esc(h.decision)}</p><div class="strategy-sources">${links(h.sources||[])}</div></article>
 <div class="strategy-heading"><h3>los próximos 90 días</h3><p>de la comprobación comparativa a la práctica permanente.</p></div><ol class="strategy-actions">${f.actions.map(a=>`<li><span>${esc(a.period)}</span><div><h4>${esc(a.title)}</h4><p>${esc(a.detail)}</p></div></li>`).join('')}</ol>
 <details class="strategy-method"><summary>¿ Por qué señales comparar a la escuela y el equipo ?</summary><ul>${f.selection.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>
 <details class="strategy-method"><summary>las condiciones de origen de la familia y lo que aún no se sabe</summary><ul>${f.assumptions.concat(f.gaps).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>
 <div class="strategy-downloads"><a class="button primary" href="downloads/STEM_family_strategy.md" download>ruta completa · texto ↓</a><a class="button secondary" href="downloads/STEM_family_strategy.json" download>estrategia y fuentes · JSON ↓</a><button class="button secondary" data-view="schools">comparar todas las escuelas</button><button class="button secondary" data-view="leagues">Reglamentos de las ligas ↗</button></div>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 let selector;
 if(b.dataset.strategyScenario){strategyScenario=b.dataset.strategyScenario;strategyCountry=DATA.family_strategy.scenarios.find(x=>x.id===strategyScenario).iso;selector=`[data-strategy-scenario="${strategyScenario}"]`}
 if(b.dataset.strategyChild){strategyChild=b.dataset.strategyChild;selector=`[data-strategy-child="${strategyChild}"]`}
 if(b.dataset.strategyCountry){strategyCountry=b.dataset.strategyCountry;selector=`[data-strategy-country="${strategyCountry}"]`}
 if(b.dataset.strategyHorizon){strategyHorizon=b.dataset.strategyHorizon;selector=`[data-strategy-horizon="${strategyHorizon}"]`}
 if(selector){renderFamilyStrategy();document.querySelector(selector).focus({preventScroll:true})}
});
